int OnCalculate(const int rates_total,      // número total de barras
                const int prev_calculated,  // barras calculadas previamente
                const datetime &time[],     // tempos
                const double &open[],       // preços de abertura
                const double &high[],       // preços de máxima
                const double &low[],        // preços de mínima
                const double &close[],      // preços de fechamento
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
{
    // Define o ponto de início seguro para o loop
    int start = MathMax(prev_calculated + 1, 0);

    for (int i = start; i < rates_total; i++)
    {
        // Calcula a máxima e mínima considerando até a barra atual 'i'
        // Usamos iHigh(iHigh) para garantir que pegue o máximo até esse ponto específico
        double highPoint = findHigh(i); 
        double lowPoint = findLow(i);

        // Verifica se a máxima desta barra ultrapassa a máxima histórica até agora
        if (high[i] > highPoint)
        {
            BuyEntryBuffer[i] = high[i];
            TPBuffer[i] = high[i] + Tppoints * _Point;
            SLBuffer[i] = high[i] - Slpoints * _Point;
        }

        // Verifica se a mínima desta barra ultrapassa a mínima histórica até agora
        if (low[i] < lowPoint)
        {
            SellEntryBuffer[i] = low[i];
            TPBuffer[i] = low[i] - Tppoints * _Point;
            SLBuffer[i] = low[i] + Slpoints * _Point;
        }

        // Importante: Se nenhuma condição for atendida, limpa os buffers para não deixar traços antigos
        else
        {
            BuyEntryBuffer[i] = 0;
            SellEntryBuffer[i] = 0;
            TPBuffer[i] = 0;
            SLBuffer[i] = 0;
        }
    }

    return (rates_total);
}

