//+------------------------------------------------------------------+
double findHigh(int bar_index)
{
    double highest = 0;
    // Percorre todas as barras anteriores até a bar_index atual
    for (int i = 0; i <= bar_index; i++)
    {
        double h = iHigh(_Symbol, PERIOD_CURRENT, i);
        if (h > highest) highest = h;
    }
    return highest;
}

//+------------------------------------------------------------------+
//| Função para encontrar a mínima até a barra 'bar_index'           |
//+------------------------------------------------------------------+
double findLow(int bar_index)
{
    double lowest = DBL_MAX;
    // Percorre todas as barras anteriores até a bar_index atual
    for (int i = 0; i <= bar_index; i++)
    {
        double l = iLow(_Symbol, PERIOD_CURRENT, i);
        if (l < lowest) lowest = l;
    }
    return lowest;
}
